    # Sparse parallel diagonals encode a periodic diagonal color pattern.
    for period in range(1, max(h, w) + 1):
        colors = {}
        for diagonal, color in samples:
            residue = diagonal % period
            if residue in colors and colors[residue] != color:
                break
            colors[residue] = color
        else:
